Given a number, in the form of an array num[] of size n containing digits from 1 to 9(inclusive). Find the next smallest palindrome strictly larger than the given number.Input: num[] = [9, 4, 1, 8, 7, 9, 7, 8, 3, 2, 2]Output: [9, 4, 1, 8, 8, 0, 8, 8, 1, 4, 9]Explanation: Next smallest palindrome is 9 4 1 8 8 0 8 8 1 4 9Input: num[] = [2, 3, 5, 4, 5]Output: [2, 3, 6, 3, 2]Explanation: Next smallest palindrome is 2 3 6 3 2Try It YourselfTable of ContentTry All Possible Numbers Using Mirror and Carry Propagation - O(n) time and O(n) spaceTry All Possible Numbers The idea is to keep adding 1 to the number and check if it becomes a palindrome. Stop when a palindrome is found.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int checkPalindrome(vector<int>& num) {
    int n = num.size();
    for (int i = 0; i < n / 2; ++i) {
        if (num[i] != num[n - 1 - i]) {
            return 0;
        }
    }
    return 1;
}

vector<int> nextPalindrome(vector<int>& num) {
    int n = num.size();

    while (true) {

        // Add 1 to the number (always do this first)
        int carry = 1;
        for (int i = n - 1; i >= 0; --i) {
            num[i] += carry;
            if (num[i] == 10) {
                num[i] = 0;
                carry = 1;
            } else {
                carry = 0;
                break;
            }
        }

        // If carry remains, insert 1 at beginning
        if (carry == 1) {
            num.insert(num.begin(), 1);
            n++;
        }

        // Check if palindrome
        if (checkPalindrome(num)) {
            break;
        }
    }

    return num;
}

int main() {
    vector<int> num = {9, 4, 1, 8, 7, 9, 7, 8, 3, 2, 2};

    vector<int> res = nextPalindrome(num);

    for (int i = 0; i < res.size(); ++i) {
        cout << res[i] << " ";
    }
    cout << endl;

    return 0;
}


