    vector<int> num = {9, 4, 1, 8, 7, 9, 7, 8, 3, 2, 2};
    vector<int> result = nextPalindrome(num);

    for (int i : result) {
        cout << i << " ";
    }
    cout << endl;
    return 0;
}


